package com.gymmind.membership.infrastructure.persistence; import com.gymmind.membership.domain.model.PaymentRecord; import com.gymmind.membership.domain.repository.PaymentRecordRepository; import org.springframework.stereotype.Repository; import java.util.Optional; @Repository class JpaPaymentRecordRepository implements PaymentRecordRepository{private final SpringDataPaymentRecordRepository d;JpaPaymentRecordRepository(SpringDataPaymentRecordRepository d){this.d=d;}public PaymentRecord save(PaymentRecord p){return d.save(p);}public Optional<PaymentRecord> findByTenantIdAndReference(Long t,String r){return d.findByTenantIdAndReference(t,r);}}
